"""Password registration and login verification per org-owasp policy."""
import password_store as _store


def register_password(password: str) -> str:
    """Hash a new password for storage following current OWASP policy."""
    # The policy requires using the recommended algorithm for new hashes,
    # which is bcrypt with work factor 12 as per password_store.hash_new_password.
    return _store.hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login attempt against any stored password hash format."""
    return _store.verify_password(password, stored)
